#include <bits/stdc++.h>
using namespace std;

long long factorial(int n) {
    long long res = 1;
    for (int i = 2; i <= n; ++i) {
        res *= i;
    }
    return res;
}

long long calc_perm(int n, int k) {
    return factorial(n) / factorial(n - k);
}

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);
    int total_n, modulus;
    cin >> total_n >> modulus;
    if (total_n == 1) {
        cout << 0 << "\n";
        return 0;
    }
    vector<long long> sequence(1, 1);
    long long total_value = 0;
    for (int i = 2; i <= total_n; ++i) {
        int size = ((i - 1) * i) / 2 + 1;
        vector<long long> new_sequence(size, 0);
        vector<long long> cum_sum(sequence.size() + 1, 0);
        for (int index = (int)sequence.size() - 1; index >= 0; --index) {
            cum_sum[index] = (cum_sum[index + 1] + sequence[index]) % modulus;
        }
        for (int w = 0; w < size; ++w) {
            int left_bound = max(0, w + 1 - i);
            int right_bound = min((int)sequence.size() - 1, w);
            new_sequence[w] = (cum_sum[left_bound] - cum_sum[right_bound + 1]) % modulus;
            if (new_sequence[w] < 0) new_sequence[w] += modulus;
        }
        vector<long long> e_array(cum_sum.size(), 0);
        vector<long long> f_array(cum_sum.size(), 0);
        for (size_t w = 0; w + 1 < e_array.size(); ++w) {
            e_array[w + 1] = (e_array[w] + cum_sum[w]) % modulus;
            f_array[w + 1] = (f_array[w] - (long long)w * cum_sum[w]) % modulus;
        }
        size_t R_idx = sequence.size();
        long long temp_b_value = 0;
        int start_jj = max(0, (int)sequence.size() - i);
        for (int jj = start_jj; jj < (int)sequence.size() - 1; ++jj) {
            int L_idx = jj + 2;
            long long val = (((e_array[R_idx] - e_array[L_idx]) % modulus + modulus) % modulus) * (i + 1 + jj) % modulus;
            val = (val + ((f_array[R_idx] - f_array[L_idx]) % modulus + modulus) % modulus) % modulus;
            val = (val * sequence[jj]) % modulus;
            temp_b_value = (temp_b_value + val) % modulus;
        }
        for (int jj = 0; jj <= (int)sequence.size() - i - 1; ++jj) {
            int L_idx = jj + 2;
            int R_idx = i + jj;
            long long val = (((e_array[R_idx + 1] - e_array[L_idx]) % modulus + modulus) % modulus) * (i + 1 + jj) % modulus;
            val = (val + ((f_array[R_idx + 1] - f_array[L_idx]) % modulus + modulus) % modulus) % modulus;
            val = (val * sequence[jj]) % modulus;
            temp_b_value = (temp_b_value + val) % modulus;
        }
        total_value = (total_value + (temp_b_value * calc_perm(total_n, total_n - i)) % modulus) % modulus;
        sequence = new_sequence;
    }
    cout << total_value % modulus << "\n";
    return 0;
}

